<div class="section-heading"><div><div class="eyebrow">White-label</div><h1>Domínio personalizado</h1><p class="text-secondary mb-0">Use algo como agenda.suaempresa.com.br no plano que inclui este recurso.</p></div></div><div class="card mb-4"><div class="card-body"><form method="post" action="/domains" class="d-flex gap-2"><?=
\App\Core\CSRF::field()?><input class="form-control" name="domain" placeholder="agenda.suaempresa.com.br" required><button class="btn btn-primary">Adicionar</button></form></div></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Domínio</th><th>Status</th><th>Validação DNS</th><th></th></tr></thead><tbody><?php foreach($domains as $d):?><tr><td><strong><?=htmlspecialchars($d['domain'])?></strong></td><td><span class="badge text-bg-<?=$d['status']==='verified'?'success':($d['status']==='failed'?'danger':'warning')?>"><?=htmlspecialchars($d['status'])?></span></td><td><code>_agenda-verification.<?=htmlspecialchars($d['domain'])?></code><small class="d-block text-secondary">TXT: <?=htmlspecialchars($d['verification_token'])?></small></td><td><div class="d-flex gap-2"><?php if($d['status']!=='disabled'):?><form method="post" action="/domains/<?=(int)$d['id']?>/verify"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-primary">Verificar DNS</button></form><form method="post" action="/domains/<?=(int)$d['id']?>/disable" onsubmit="return confirm('Desativar este domínio?')"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-danger">Desativar</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$domains):?><tr><td colspan="4" class="empty-state">Nenhum domínio configurado.</td></tr><?php endif;?></tbody></table></div></div>
